<?php declare(strict_types=1); return static fn(PDO $db)=>$db->exec("CREATE TABLE IF NOT EXISTS offre (id_offre INT AUTO_INCREMENT PRIMARY KEY,client_id INT NULL,num_offre VARCHAR(100) NOT NULL,date_offre DATE NOT NULL,date_limite_reponse DATE NULL,statut VARCHAR(30) NOT NULL DEFAULT 'en_cours',motif_perte TEXT NULL,fichier_ao VARCHAR(255),fichier_ao_original VARCHAR(255),reference_offre VARCHAR(190),titre_offre VARCHAR(255),montant_estime DECIMAL(15,2),commercial_dedie VARCHAR(190),date_creat_offre DATE,archived_at DATETIME NULL,archive_run_id INT NULL,INDEX idx_offer_client(client_id),INDEX idx_offer_status_deadline(statut,date_limite_reponse)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
